const experiments = $('Buscar testes em andamento').all().map((item) => item.json);
const logs = $('Carregar envios rastreados').all().map((item) => item.json);
const now = new Date().toISOString();

const metricsFor = (rows) => {
  const sent = rows.filter((r) => String(r.status || '').toUpperCase() === 'SENT').length;
  const clicked = rows.filter((r) => Number(r.click_count || 0) > 0).length;
  const purchases = rows.filter((r) => Boolean(r.converted_at)).length;
  const revenue = rows.reduce((sum, r) => sum + Number(r.converted_revenue || 0), 0);
  return {
    sent,
    clicked,
    purchases,
    revenue: Number(revenue.toFixed(2)),
    click_rate: sent ? Number(((clicked / sent) * 100).toFixed(2)) : 0,
    conversion_rate: sent ? Number(((purchases / sent) * 100).toFixed(2)) : 0,
    revenue_per_sent: sent ? Number((revenue / sent).toFixed(4)) : 0,
  };
};

const hashSeed = (value) => {
  let hash = 2166136261;
  for (const char of String(value)) {
    hash ^= char.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
};

const makeRandom = (seedValue) => {
  let state = hashSeed(seedValue) || 1;
  return () => {
    state += 0x6D2B79F5;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
};

const normalSample = (random) => {
  const u1 = Math.max(random(), 1e-12);
  const u2 = random();
  return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
};

const gammaSample = (shape, random) => {
  if (shape < 1) {
    return gammaSample(shape + 1, random) * Math.pow(Math.max(random(), 1e-12), 1 / shape);
  }
  const d = shape - 1 / 3;
  const c = 1 / Math.sqrt(9 * d);
  for (;;) {
    const x = normalSample(random);
    const vBase = 1 + c * x;
    if (vBase <= 0) continue;
    const v = vBase * vBase * vBase;
    const u = random();
    if (u < 1 - 0.0331 * x * x * x * x) return d * v;
    if (Math.log(Math.max(u, 1e-12)) < 0.5 * x * x + d * (1 - v + Math.log(v))) return d * v;
  }
};

const betaSample = (successes, failures, random) => {
  const x = gammaSample(successes + 1, random);
  const y = gammaSample(failures + 1, random);
  return x / (x + y);
};

const posteriorComparison = (control, challenger, seedValue) => {
  const random = makeRandom(seedValue);
  const draws = 20000;
  let challengerBetter = 0;
  let challengerLiftFive = 0;
  let controlLiftFive = 0;
  for (let i = 0; i < draws; i++) {
    const controlRate = betaSample(control.purchases, Math.max(0, control.sent - control.purchases), random);
    const challengerRate = betaSample(challenger.purchases, Math.max(0, challenger.sent - challenger.purchases), random);
    if (challengerRate > controlRate) challengerBetter++;
    if (challengerRate >= controlRate * 1.05) challengerLiftFive++;
    if (controlRate >= challengerRate * 1.05) controlLiftFive++;
  }
  return {
    method: 'beta_binomial_monte_carlo',
    draws,
    probability_challenger_better: Number((challengerBetter / draws).toFixed(4)),
    probability_challenger_lift_5pct: Number((challengerLiftFive / draws).toFixed(4)),
    probability_control_lift_5pct: Number((controlLiftFive / draws).toFixed(4)),
    confidence_threshold: 0.9,
    minimum_business_lift: 0.05,
  };
};

return experiments.map((experiment) => {
  const platform = String(experiment.platform || 'hotmart');
  const rows = logs.filter((r) =>
    String(r.copy_experiment_id || '') === String(experiment.id) &&
    String(r.platform || 'hotmart') === platform
  );
  const control = metricsFor(rows.filter((r) => String(r.copy_variant_id || '') === String(experiment.champion_variant_id)));
  const challenger = metricsFor(rows.filter((r) => String(r.copy_variant_id || '') === String(experiment.challenger_variant_id)));
  const minSends = Number(experiment.minimum_sends_per_variant || 100);
  const minPurchases = Number(experiment.minimum_purchases_total || 5);
  const purchasesTotal = control.purchases + challenger.purchases;
  const stats = posteriorComparison(control, challenger, [experiment.id, control.sent, control.purchases, challenger.sent, challenger.purchases].join(':'));

  let decision = 'insufficient_data';
  let reason = 'Ainda não existem 10 envios válidos de cada versão para concluir a triagem.';

  if (['perfectpay', 'hotmart'].includes(platform) && String(experiment.primary_metric || '') === 'click_rate') {
    if (control.sent >= minSends && challenger.sent >= minSends) {
      if (control.clicked === 0 && challenger.clicked === 0) {
        decision = 'technical_stop';
        reason = '[TRIAGEM] As duas versões ficaram sem cliques após 20 envios. A rodada foi encerrada para receber novos ângulos.';
      } else if (control.clicked > challenger.clicked) {
        decision = 'champion_wins';
        reason = '[TRIAGEM] Versão A promissora: gerou mais cliques que a versão B. Ainda não é campeã; deve enfrentar uma nova alternativa.';
      } else if (challenger.clicked > control.clicked) {
        decision = 'challenger_wins';
        reason = '[TRIAGEM] Versão B promissora: gerou mais cliques que a versão A. Ainda não é campeã; deve enfrentar uma nova alternativa.';
      } else {
        decision = 'keep_running';
        reason = '[TRIAGEM] Empate em cliques após 20 envios. Nenhuma campeã foi definida; a próxima rodada deve testar um novo ângulo.';
      }
    }
  } else if (control.sent >= minSends && challenger.sent >= minSends && purchasesTotal >= minPurchases) {
    const challengerRevenueGuard = challenger.revenue_per_sent >= control.revenue_per_sent * 1.05 ||
      (control.revenue_per_sent === 0 && challenger.revenue_per_sent > 0);
    const controlRevenueGuard = control.revenue_per_sent >= challenger.revenue_per_sent * 1.05 ||
      (challenger.revenue_per_sent === 0 && control.revenue_per_sent > 0);

    if (stats.probability_challenger_lift_5pct >= 0.9 && challengerRevenueGuard) {
      decision = 'challenger_wins';
      reason = 'A desafiante atingiu pelo menos 90% de probabilidade de superar o controle em 5% ou mais, com receita por envio também superior.';
    } else if (stats.probability_control_lift_5pct >= 0.9 && controlRevenueGuard) {
      decision = 'champion_wins';
      reason = 'O controle atingiu pelo menos 90% de probabilidade de superar a desafiante em 5% ou mais, com receita por envio também superior.';
    } else {
      decision = 'keep_running';
      reason = 'A amostra mínima foi atingida, mas a confiança estatística ou a vantagem de receita ainda não é suficiente; o teste continua.';
    }
  }

  return {
    json: {
      platform,
      experiment_id: experiment.id,
      window_start: experiment.started_at || experiment.created_at,
      window_end: now,
      champion_metrics: { ...control, label: 'control', statistical: stats },
      challenger_metrics: { ...challenger, label: 'challenger', statistical: stats },
      decision,
      reason,
      promoted: false,
    },
  };
});
